sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float brightness;
uniform float contrast;
uniform float saturation;
uniform float vibrance;
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return half4(0.0);
    float3 f = float3(c.rgb) / float(c.a);
    f = clamp(f + brightness + contrast * (dot(f, float3(0.299, 0.587, 0.114)) - 0.5), 0.0, 1.0);
    float y = dot(f, float3(0.299, 0.587, 0.114));
    float2 uv = float2(dot(f, float3(-0.14713, -0.28886, 0.436)), dot(f, float3(0.615, -0.51499, -0.10001)));
    float gain = 1.0 + vibrance * max(1.0 - 2.52 * length(uv), 0.0);
    f = float3(y) + (f - float3(y)) * saturation * gain;
    return half4(half3(clamp(f, 0.0, 1.0)) * c.a, c.a);
}
